dtsPropsFor.StatTile:
/** Already-translated label. Rendered uppercase mono. */
label: string;
/**
 * THREE STATES, chosen by these two props (the component's type is a union; this contract flattens it):
 * - known: `value` is the caller's formatted string ("5,6 %", "1,30 M€");
 * - unknown: `value={null}` AND `unknownLabel` — a long dash and a "not measured" word, never a zero;
 * - hidden: `hidden` AND `hiddenLabel`, and NO `value` at all — not in the text, not in an attribute.
 *   A blurred decoy of shapes stands in; a value in the DOM is known to anyone who opens devtools.
 */
value?: string | null;
/** Required with `value={null}`: the dash alone says nothing to a screen reader. */
unknownLabel?: string;
hidden?: boolean;
/** Hidden state only: shown sharp, at full opacity, under the blurred decoy ("not on your dashboard"). */
hiddenLabel?: string;
/** Hidden state only: read by screen readers only ("hidden until December"). */
hiddenNote?: string;
/** Known/unknown only. A line under the figure. */
sub?: string;
/**
 * Known only. `text` carries a SIGN and a WORD ("−0.4 pt · better") — never colour alone; U+2212 for minus.
 * Colour = direction × sentiment (a churn going down is good); `flat` is never coloured.
 */
delta?: { text: string; direction: "up" | "down" | "flat"; sentiment?: "good" | "bad" };
/** A meter under the figure. `value` 0–100; `null` = not measured, drawn hatched, never an empty bar (which reads as zero). */
bar?: { value: number | null; tone: "good" | "bad" | "neutral" };
/** Known only: lifts the blur a hidden tile was showing, once. Off under reduced motion. */
revealing?: boolean;
/** `hero` = the stencil figure (48px, 30px under 760px) — ONE per dashboard. `md` = mono 20px. `compact` = mono 17px. */
size?: "hero" | "md" | "compact";
/** Known/unknown only: a small chart under the figure — a mini `BulletChart`, never a second number. */
children?: React.ReactNode;
className?: string;
"data-testid"?: string;

dtsPropsFor.Sparkline:
/** One series, one slot per entry. `null` is an unknown or not-yet-played period: a GAP in the line, never a zero. */
values: readonly (number | null)[];
/** The scale, chosen by the caller and never fitted to the data. A value outside it sits on the edge and the end marker turns hollow. */
min: number;
max: number;
/** Gridline values. Outside `[min, max]` they are dropped, not clamped. */
ticks?: readonly number[];
/** Formats a tick label — the same formatter as the rest of the screen. */
formatTick?: (value: number) => string;
/** A dashed red line (an objective, a threshold) WITH its label — the red dash never speaks alone. Outside `[min, max]` it is not drawn. */
reference?: { value: number; label: string };
/** One per entry of `values` (month initials): same slots, same order. */
xLabels?: readonly string[];
/** The last known value, formatted — the SAME string the matching tile or cell shows. */
endLabel?: string;
/** Required: the chart's text equivalent, stating the TREND ("from 6.0% in January to 4.1% in December"). Everything drawn is aria-hidden. */
ariaLabel: string;
/** `md` 160px tall, for a ChartFrame. `sm` 64px, inline next to a figure. */
size?: "md" | "sm";
/** Draws the line in once (800ms). Off under reduced motion. */
animate?: boolean;
className?: string;
"data-testid"?: string;

dtsPropsFor.EventClipping:
/** The component's type is a union on `kind`; this contract flattens it. */
kind: "viral" | "control" | "reports" | "press" | "competitor";
/** `viral` only — a post, not an article: a fictional handle ("@endless_evening"). */
handle?: string;
/** Every kind but `viral`: a fictional outlet, or SignalConso, the public platform the event names. */
masthead?: string;
/** Every kind but `viral`. */
headline?: string;
/** The body: the post's text, or the article's standfirst. */
text: string;

dtsPropsFor.PhoneMock:
/**
 * Top to bottom, the elements of Flixo's cancellation screen. One `cancel` entry, always; the rest appear as cards
 * put them in production (the game computes the list — `phoneView` in lib/game/view.ts).
 */
items: readonly (
  | { kind: "appBar" }
  | { kind: "streakPush" }
  | { kind: "crumbs"; buried: boolean }
  | { kind: "plan"; annual: boolean }
  | { kind: "socialProof" }
  | { kind: "reminder" }
  | { kind: "cancel"; variant: "phone" | "pauseFirst" | "buriedLink" | "button"; buried: boolean }
  | { kind: "pauseOffer" }
  | { kind: "retentionOffers"; shamed: boolean }
  | { kind: "areYouSure" }
  | { kind: "exitSurvey" }
  | { kind: "noticePeriod" }
  | { kind: "effectiveToday" }
)[];
/** Every string on the screen, resolved in the page's language. `call` carries a `{number}` slot. */
labels: {
  caption: string; appName: string; time: string; streakPush: string; crumbs: string; crumbsBuried: string;
  plan: string; planAnnual: string; price: string; priceAnnual: string; social: string; reminder: string;
  number: string; call: string; pauseButton: string; cancelLink: string; cancelLinkBuried: string;
  cancelButton: string; pauseOffer: string; pauseAccept: string; pauseDecline: string;
  cascadeOffers: readonly string[]; stay: string; decline: string; declineShamed: string; confirm: string;
  survey: string; surveyAnswers: readonly string[]; notice: string; threeClicks: string;
};
className?: string;
